// Simulated layout engine. No real DOM, no timers — a read/write log.
let reflows = 0;
let dirty = false;            // layout-dirty flag
const geom = {};              // pretend computed geometry per row id

function readOffsetWidth(id) {
  // Reading geometry forces a synchronous flush IFF layout is dirty.
  if (dirty) { reflows++; dirty = false; }   // one full layout pass
  return geom[id] ?? 100;
}
function writeWidth(id, px) {
  geom[id] = px;
  dirty = true;               // a style write marks layout dirty
}

const rows = [1, 2, 3, 4, 5, 6, 7, 8];

// BAD: read-then-write interleaved → one forced layout per row.
function thrash() {
  reflows = 0; dirty = true;  // an earlier write left layout dirty
  for (const id of rows) {
    const w = readOffsetWidth(id);   // flush (layout dirty from prev iter)
    writeWidth(id, w + 10);          // dirty again
  }
  return reflows;
}

// GOOD: two-pass batch → all reads, then all writes → one layout.
function twoPass() {
  reflows = 0; dirty = true;
  const widths = [];
  for (const id of rows) widths.push(readOffsetWidth(id)); // pass 1: reads flush once, then stay clean
  for (let i = 0; i < rows.length; i++) writeWidth(rows[i], widths[i] + 10); // pass 2: writes only
  return reflows;
}

const bad = thrash();
const good = twoPass();
console.log(`thrash=${bad} batch=${good}`);
